import{_ as i,o as l,c as t,j as e,a as n,a3 as r}from"./chunks/framework.z_KJ15Ep.js";const p=JSON.parse('{"title":"Abschlusszeugnisse an der Berufsschule erstellen","description":"","frontmatter":{"title":"Abschlusszeugnisse an der Berufsschule erstellen","source_pageid":1358,"source_revision":6864},"headers":[],"relativePath":"zeugnisse/berufskolleg/erstellen-von-abschlusszeugnissen-am-bk-tutorial.md","filePath":"zeugnisse/berufskolleg/erstellen-von-abschlusszeugnissen-am-bk-tutorial.md"}'),u={name:"zeugnisse/berufskolleg/erstellen-von-abschlusszeugnissen-am-bk-tutorial.md"};function a(o,s,d,c,h,g){return l(),t("div",null,[...s[0]||(s[0]=[e("h1",{id:"abschlusszeugnisse-an-der-berufsschule-erstellen",tabindex:"-1"},[n("Abschlusszeugnisse an der Berufsschule erstellen "),e("a",{class:"header-anchor",href:"#abschlusszeugnisse-an-der-berufsschule-erstellen","aria-label":'Permalink to "Abschlusszeugnisse an der Berufsschule erstellen"'},"​")],-1),e("p",null,"Bereiten Sie Noten, abgeschlossene Fächer und weitere Zeugnisangaben für die Berufsschule vor. Der Artikel ergänzt den Ablauf zur BK-Abschlussberechnung.",-1),e("div",{"data-hint-kind":"tip",class:"tip custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"tip","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"M9 18h6m-5 3h4m-5-6c-4-3-4-9 0-11 5-3 11 1 9 6-.5 2-2 3-3 5v1H9z"})]),n("Tipp")]),e("p",null,"Grundsätzlich gelten die anderen Tutorials zum Erstellen von Zeugnissen und zum Schuljahresabschluss auch für das Berufskolleg."),e("p",null,[n("Konsultieren Sie für Abschlüsse am Berufskolleg zusätzlich den Artikel zum Reiter "),e("em",null,"Schüler ➜ BK-Abschluss"),n(".")])],-1),r('<p>Im Folgenden finden Sie eine Kurzanleitung für die Berufsschule in SchILD-NRW 3.</p><h2 id="noteneingabe" tabindex="-1">Noteneingabe <a class="header-anchor" href="#noteneingabe" aria-label="Permalink to &quot;Noteneingabe&quot;">​</a></h2><ol><li>Für die Eingabe der Noten müssen die aktuellen Fächer mit Lehrkräften unter <em>Schüler ➜ Akt. Halbjahr ➜ Leistungsdaten</em> eingetragen sein. Diese Zuweisung erfolgt über <em>Stundentafeln</em> und die zugehörigen Gruppenprozesse.</li><li>Anschließend erfassen die Fachlehrkräfte die Noten über den an der Schule eingerichteten Erfassungsweg. Für GradeHub und WeNoM beachten Sie die <a href="/zeugnisse/noteneingabe.html">Hinweise zur Noteneingabe</a> und die dort verlinkte SVWS-Dokumentation.</li><li>Die Noten werden eingesammelt. Zusätzlich werden über den Gruppenprozess <strong>Abgeschlossene Fächer holen</strong> die entsprechenden Fächer übernommen. Dabei ist einzustellen, ob auch Noten aus vorherigen Bildungsgängen übernommen werden sollen, zum Beispiel wenn auf einen zweijährigen Ausbildungsberuf aufgesattelt wurde.</li><li>Fehlende, im aktuellen Halbjahr nicht unterrichtete Fächer werden über den Gruppenprozess <strong>Stundentafel zuweisen</strong> in die Leistungsdaten übernommen. Erst dadurch können diese Fächer auf dem Zeugnis erscheinen.</li></ol><p>Über einen passenden Report kann eine Zensurenübersicht für die Klasse erzeugt werden, die in der Zeugniskonferenz verwendet werden kann.</p><h2 id="einstellen-der-ubrigen-daten" tabindex="-1">Einstellen der übrigen Daten <a class="header-anchor" href="#einstellen-der-ubrigen-daten" aria-label="Permalink to &quot;Einstellen der übrigen Daten&quot;">​</a></h2><p>Mit dem Zeugniskonferenzprotokoll kann anschließend die Erstellung der Zeugnisse vorbereitet werden.</p><ul><li>Über Gruppenprozesse lassen sich das Konferenzdatum und das Zeugnisdatum setzen.</li><li>Für die korrekte Ermittlung der FOR-Abschlüsse ist der Englisch-Sprachstand zu erfassen. Wenn Englisch erteilt wurde, kann dies über folgende Gruppenprozesse erfolgen: <ul><li><strong>Sprachenfolge aus Leistungsdaten holen</strong></li><li><strong>Sprach-Referenzniveaus ermitteln</strong></li></ul></li></ul>',7),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),n("Hinweis")]),e("p",null,"Achten Sie darauf, dass die Leistungsdaten vollständig und korrekt vorliegen. Führen Sie nach manuellen Eintragungen – etwa bei Sprachniveaus – die entsprechenden Gruppenprozesse nicht erneut aus, da automatische Prozesse manuelle Änderungen überschreiben können.")],-1),e("p",null,[n("Für den Mittleren Schulabschluss ist der erforderliche Nachweis der Englischkenntnisse zu prüfen, auch wenn im aktuellen Bildungsgang kein Englisch unterrichtet wurde. Ein Eintrag des Sprachniveaus allein ersetzt diesen Nachweis nicht. Zulässige Nachweise nennt "),e("a",{href:"https://bass.schule.nrw/3129.htm",target:"_blank",rel:"noreferrer"},"VV 9.4.1 zu § 9 Anlage A APO-BK"),n(". Vorliegende, geprüfte Angaben werden unter "),e("em",null,"Laufbahninfo"),n(" dokumentiert.")],-1),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),n("Hinweis")]),e("p",null,"Konsultieren Sie zu den Gruppenprozessen zum BK-Abschluss die weiterführenden Artikel. Der Bereich der Gruppenprozesse zum BK-Abschluss ist nur aktiv, wenn alle ausgewählten Schülerinnen und Schüler dem gleichen Jahrgang angehören. Gegebenenfalls müssen die Gruppenprozesse getrennt nach Jahrgangsgruppen durchgeführt werden.")],-1),r("<ul><li><p>Führen Sie anschließend die Gruppenprozesse zum BK-Abschluss durch. Diese Prozesse führen schrittweise durch das Verfahren. Das konkrete Vorgehen hängt vom jeweiligen Abschluss des Bildungsgangs und von der Schülergruppe ab.</p><ul><li><strong>Leistungsdaten holen</strong> kopiert die aktuellen Noten in den Reiter <em>BK-Abschluss</em>.</li><li><strong>A01: Abschluss berechnen</strong> berechnet Abschluss und Durchschnittsnote. Die Hinweise sind zu beachten und mit den Ergebnissen der Zeugniskonferenz abzugleichen. Abweichungen sollten geprüft und geklärt werden.</li></ul></li><li><p><strong>A02 (FHR)</strong>: Hier sind folgende Gruppenprozesse durchzuführen:</p><ul><li><strong>Zulassung prüfen</strong></li><li><strong>Prüfungsnoten eingeben</strong> (aus den FHR-Prüfungen)</li><li><strong>Vorläufige Abschlussnoten berechnen</strong></li><li><strong>Mündliche Prüfungen festlegen</strong> (Eintrag im Reiter <em>BK-Abschluss</em>)</li><li><strong>Abschluss berechnen</strong></li></ul></li><li><p>Anschließend können die Schülerinnen und Schüler mit identischem Zeugnisformular ausgewählt und die Zeugnisse erstellt werden. Dabei sollten die Zeugnisse auch archiviert werden.</p></li></ul><p>Der Zeugnisdruck ist jeweils getrennt für den konkreten Abschluss beziehungsweise für die erforderlichen Reports der Abgangszeugnisse zu wiederholen.</p>",2),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),n("Hinweis – Siehe auch")]),e("ul",null,[e("li",null,[e("a",{href:"/reporting/zeugnisformulare/zeugnisse-themenuebersicht.html"},"Den Zeugnisdruck vorbereiten")]),e("li",null,[e("a",{href:"/reporting/zeugnisformulare/zeugnisformulare-herunterladen-und-aktualisieren.html"},"Zeugnisformulare herunterladen und bereitstellen")])])],-1),e("hr",null,null,-1),e("p",null,[e("a",{href:"https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Erstellen_von_Abschlusszeugnissen_am_BK_(Tutorial)",target:"_blank",rel:"noreferrer"},"Originalartikel im Wiki"),n(" · Quellrevision 6864.")],-1)])])}const f=i(u,[["render",a]]);export{p as __pageData,f as default};
